<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { api, ApiError } from '../../shared/api/client'
import type { Task } from '../../shared/types/domain'
import StatusBadge from '../../shared/components/StatusBadge.vue'
const tasks = ref<Task[]>([]); const active = ref<Task | null>(null); const scanCode = ref(''); const message = ref(''); const checking = ref(false)
onMounted(async () => { tasks.value = await api<Task[]>('/pickup-tasks?mine=true'); active.value = tasks.value[0] ?? null })
async function command(action: 'respond'|'arrive'|'scan'|'shipper-confirm', payload: Record<string, unknown> = {}) { if (!active.value) return; checking.value=true; message='Đang kiểm tra với máy chủ…'; try { active.value=await api<Task>(`/pickup-tasks/${active.value.id}/${action}`, { method:'POST', headers:{'Idempotency-Key':crypto.randomUUID()}, body:JSON.stringify({version:active.value.version,...payload}) }); tasks.value=tasks.value.map(x=>x.id===active.value!.id?active.value!:x); message=active.value.status==='handed_over'?'Đã bàn giao và phát hành biên nhận.':'Máy chủ đã ghi nhận thao tác.' } catch(e) { message=e instanceof ApiError?e.message:'Chưa đồng bộ — hãy kiểm tra lại trước khi thử lại.' } finally { checking.value=false } }
const allScanned = computed(()=>!!active.value && active.value.scannedCodes.length===active.value.packages.length)
</script>
<template><main class="mobile-shell"><header><p>Nhiệm vụ tại kho</p><h1>Chào, shipper</h1></header><p v-if="checking" class="sync">Đang kiểm tra trạng thái trên máy chủ…</p><p v-if="message" class="notice">{{ message }}</p><section v-if="active" class="task"><div class="row"><div><small>{{ active.code }}</small><h2>{{ active.warehouseName }}</h2></div><StatusBadge :status="active.status"/></div><p>{{ active.packages.length }} kiện cần đối chiếu. QR chỉ định danh kiện; quyền do máy chủ quyết định.</p><div class="progress">Đã quét {{ active.scannedCodes.length }}/{{ active.packages.length }} kiện</div><button v-if="!active.shipperAccepted" @click="command('respond',{accepted:true})">Nhận nhiệm vụ</button><button v-else-if="!active.arrivedAtWarehouse" @click="command('arrive')">Tôi đã đến kho</button><template v-else><label>Mã kiện<input v-model="scanCode" placeholder="Nhập hoặc quét QR" @keyup.enter="command('scan',{package_code:scanCode});scanCode=''"/></label><button @click="command('scan',{package_code:scanCode});scanCode=''" :disabled="!scanCode">Quét kiện</button><button class="outline" :disabled="!allScanned || active.status==='handed_over'" @click="command('shipper-confirm')">Xác nhận nhận hàng</button><small v-if="!allScanned">Nút xác nhận bị khóa vì chưa quét đủ kiện.</small></template></section><section v-else class="empty">Chưa có nhiệm vụ được phân công.</section><nav><span>Nhiệm vụ</span><span>Quét mã</span><span>Lịch sử</span><span>Tài khoản</span></nav></main></template>
